import { money, escapeHtml } from '../../../shared/formatters.js';
import { groupedBars } from '../../../shared/charts.js';
import { panel, emptyState } from '../../../shared/ui.js';
import { ledger, option, tableRows, financeTable, legends } from '../components.js';
import { getScope, totalMetrics } from '../repository.js';

export function renderInvestor(snapshot, state) {
    const all = snapshot.items.filter((item) => item.projectId === state.projectId && item.side === 'investor');
    if (!all.length) return panel('Chủ đầu tư', '', emptyState('Chưa có hạng mục chủ đầu tư', 'Chọn dự án khác để xem dữ liệu mẫu.'));
    const scoped = getScope(snapshot, state, 'investor');
    const totals = totalMetrics(scoped); const rows = tableRows(scoped, state, 'investor');
    const pageFilters = `<div class="tp-filter-bar tp-page-filter-bar"><div class="tp-field"><label for="item-filter">Phạm vi hạng mục</label><select id="item-filter" class="tp-select" data-field="itemId">${option('', `Tất cả hạng mục (${all.length})`, state.itemId)}${all.map((item) => option(item.id, item.name, state.itemId)).join('')}</select></div>${state.itemId ? `<button class="tp-button" data-action="reset-filters">Xem tất cả hạng mục</button>` : ''}</div>`;
    const chart = groupedBars(scoped.map((item) => ({ label: item.id === 'survey' ? 'Khảo sát' : item.id === 'basic' ? 'TK cơ sở' : 'TK kỹ thuật', values: [item.contract, item.accepted, item.paid] })), { colors: ['#4a6d82', '#0c9fb5', '#163d5c'], seriesLabels: ['HĐ cập nhật', 'Nghiệm thu', 'Tiền đã thu'], label: 'Hợp đồng, nghiệm thu, tiền đã thu theo hạng mục. Số liệu đầy đủ trong bảng bên dưới.' });
    const tableControls = `<div class="tp-table-controls"><div class="tp-field tp-search-field"><label for="table-search">Tìm trong bảng</label><input type="search" id="table-search" class="tp-input" data-field="search" value="${escapeHtml(state.search)}" placeholder="Tên hạng mục…"></div><div class="tp-field tp-sort-field"><label for="table-sort">Sắp xếp</label><select id="table-sort" class="tp-select" data-field="sort">${option('name', 'Tên hạng mục', state.sort)}${option('balance', 'Còn theo NT giảm dần', state.sort)}${option('contract', 'Hợp đồng giảm dần', state.sort)}</select></div>${state.search || state.sort !== 'name' ? `<button class="tp-button" data-action="reset-filters">Đặt lại</button>` : ''}</div>`;
    return `${pageFilters}${ledger('Phạm vi chủ đầu tư đang chọn', totals, 'investor', `${scoped.length} hạng mục · Đơn vị: tỷ đồng`)}<div class="tp-section-heading"><h2 class="tp-section-title">Tiến độ nghiệm thu và thu tiền</h2></div><div class="tp-chart-grid">${panel('Theo hạng mục', 'Đơn vị: tỷ đồng · cùng phạm vi với bảng bên dưới', `<div class="tp-chart-wrap">${chart}</div>${legends(['HĐ cập nhật', 'Nghiệm thu', 'Đã thu'], ['#4a6d82', '#0c9fb5', '#163d5c'])}`)}${panel('Số liệu bổ sung', 'Trong phạm vi hạng mục đang chọn', `<div class="tp-split-list">${[['Hợp đồng ban đầu', totals.contractOriginal], ['Sản lượng', totals.production], ['Khối lượng chưa NT', totals.unaccepted], ['Giữ lại', totals.retention], ['Còn sau giữ lại', totals.afterRetention]].map(([label, value]) => `<div class="tp-split-row"><span class="tp-split-label">${label}</span><strong class="tp-split-value">${money(value)}${value === null ? '' : ' tỷ'}</strong></div>`).join('')}</div><p class="tp-panel-caption">“Chưa đủ dữ liệu” không đồng nghĩa với 0. Giá trị phụ lục thay thế toàn bộ hợp đồng.</p>`)}</div><div class="tp-section-heading tp-table-section-head"><div><h2 class="tp-section-title">Chi tiết hạng mục</h2><p class="tp-section-caption">Hiển thị ${rows.length}/${scoped.length} dòng · Tìm kiếm và sắp xếp chỉ đổi bảng, giữ nguyên KPI</p></div>${tableControls}</div>${panel('Sổ chủ đầu tư', 'Bấm tên hạng mục để mở giao dịch', financeTable(rows, totals, 'investor', 'Tổng gồm toàn bộ phạm vi chọn, kể cả dòng bị ẩn bởi tìm kiếm'))}`;
}
